import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"搜索语法","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/search-syntax.md","filePath":"zh-CN/user-guide/search-syntax.md","lastUpdated":1787649438000}'),c={name:"zh-CN/user-guide/search-syntax.md"};function l(s,e,i,n,r,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="搜索语法" tabindex="-1">搜索语法 <a class="header-anchor" href="#搜索语法" aria-label="Permalink to &quot;搜索语法&quot;">​</a></h1><p>Lertaro 的搜索框远不止支持简单的字符检索。它配备了极速的匹配算法，支持模糊跳跃匹配、逻辑运算符、词边界修饰符、盘符与路径定位、二次过滤标记（Query Tokens）以及多语言智能别名，所有语法均可在同一条查询中自由混合使用。</p><h2 id="_1-基础匹配模式与大小写" tabindex="-1">1. 基础匹配模式与大小写 <a class="header-anchor" href="#_1-基础匹配模式与大小写" aria-label="Permalink to &quot;1. 基础匹配模式与大小写&quot;">​</a></h2><h3 id="模糊匹配-默认" tabindex="-1">模糊匹配（默认） <a class="header-anchor" href="#模糊匹配-默认" aria-label="Permalink to &quot;模糊匹配（默认）&quot;">​</a></h3><p>Lertaro 默认启用模糊匹配（Fuzzy Matching）。只需输入关键词的任意部分，只要字符按先后顺序出现在文件或文件夹名称中，即使不连续也能精准命中：</p><table tabindex="0"><thead><tr><th style="text-align:left;">输入示例</th><th style="text-align:left;">匹配结果示例</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ltro</code></td><td style="text-align:left;"><code>Lertaro.exe</code></td><td style="text-align:left;">字符按 <code>l</code> → <code>t</code> → <code>r</code> → <code>o</code> 顺序跳跃命中（<strong>L</strong>er<strong>t</strong>a<strong>ro</strong>.exe）</td></tr><tr><td style="text-align:left;"><code>vsc</code></td><td style="text-align:left;"><code>Visual Studio Code.lnk</code></td><td style="text-align:left;">命中各单词首字母（<strong>V</strong>isual <strong>S</strong>tudio <strong>C</strong>ode）</td></tr><tr><td style="text-align:left;"><code>rt-fin</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td><td style="text-align:left;">命中连续子串（Q3-repo<strong>rt-fin</strong>al.docx）</td></tr></tbody></table><p>在<strong>设置 → 通用 → 系统 → 启用模糊匹配</strong>中关闭该开关后，普通搜索词（未附加任何操作符）将转为精确子串匹配——输入 <code>abc</code> 将只匹配包含连续 <code>abc</code> 的名称，不再匹配 <code>a-b-c</code>。该开关仅改变未带修饰符的普通词，后文介绍的所有操作符行为均保持一致。</p><h3 id="大小写智能识别-smart-case" tabindex="-1">大小写智能识别（Smart Case） <a class="header-anchor" href="#大小写智能识别-smart-case" aria-label="Permalink to &quot;大小写智能识别（Smart Case）&quot;">​</a></h3><ul><li><strong>全小写查询</strong>：默认不区分大小写。例如输入 <code>myfile</code> 可命中 <code>myfile</code>、<code>MyFile</code>、<code>MYFILE</code> 等。</li><li><strong>包含大写字母</strong>：一旦词中包含任意大写字母，该词将自动转为<strong>大小写敏感</strong>。例如输入 <code>MyFile</code> 只会匹配 <code>MyFile</code>，而不会匹配全小写的 <code>myfile</code>。</li></ul><h2 id="_2-多词组合与逻辑运算" tabindex="-1">2. 多词组合与逻辑运算 <a class="header-anchor" href="#_2-多词组合与逻辑运算" aria-label="Permalink to &quot;2. 多词组合与逻辑运算&quot;">​</a></h2><h3 id="空格-and-与" tabindex="-1">空格：AND（与） <a class="header-anchor" href="#空格-and-与" aria-label="Permalink to &quot;空格：AND（与）&quot;">​</a></h3><p>多个关键词之间使用空格分隔，表示同时满足所有条件。各个关键词在文件名中出现的先后顺序<strong>不受限制</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final 2024</span></span></code></pre></div><p>上述输入可以同时命中 <code>2024-Q3-report-final.docx</code> 与 <code>final_report_2024.pdf</code>。</p><h3 id="竖线-or-或" tabindex="-1">竖线 <code>|</code>：OR（或） <a class="header-anchor" href="#竖线-or-或" aria-label="Permalink to &quot;竖线 `|`：OR（或）&quot;">​</a></h3><p>使用竖线 <code>|</code> 分隔关键词，表示满足其中任意一个条件即可：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>png | jpg | gif</span></span></code></pre></div><p>可自由混合 AND 与 OR 逻辑。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024</span></span></code></pre></div><p>表示查找包含 <code>report</code> 或 <code>summary</code>，且同时包含 <code>2024</code> 的文件。在 OR 查询中，结果名称中所有命中条件的关键词都会同步高亮显示。</p><h3 id="运算优先级-or-优先于-and" tabindex="-1">运算优先级：OR 优先于 AND <a class="header-anchor" href="#运算优先级-or-优先于-and" aria-label="Permalink to &quot;运算优先级：OR 优先于 AND&quot;">​</a></h3><p>在同一查询中混合使用空格（AND）与竖线 <code>|</code>（OR）时，<code>|</code> 的优先级<strong>高于</strong>空格：<code>|</code> 两侧的词会先合并为同一个 OR 组，空格分隔的各个组之间再取 AND。查询不支持括号，不支持用括号改变这种结合顺序。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024 | draft</span></span></code></pre></div><p>等价于 <code>(report OR summary) AND (2024 OR draft)</code>。</p><p>注意：<code>|</code> 必须作为独立词并以空格与两侧分隔，<code>a|b</code> 或 <code>a |b</code> 不会按 OR 解析；也不要把 <code>!</code> 排除词放进 <code>|</code> 的 OR 组（如 <code>b | !c</code>），它会被解析为「b 匹配或 c 不匹配」，若想排除某个词，请让它作为独立的空格条件（如 <code>b !c</code>）。</p><h3 id="词内空格与短语引用" tabindex="-1">词内空格与短语引用 <a class="header-anchor" href="#词内空格与短语引用" aria-label="Permalink to &quot;词内空格与短语引用&quot;">​</a></h3><p>若要搜索本身包含空格的短语，可以使用反斜杠转义空格 <code>\\ </code>，或使用单引号 <code>&#39;...&#39;</code> / 双引号 <code>&quot;...&quot;</code> 包裹短语：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>final\\ report</span></span>\n<span class="line"><span>&#39;final report&#39;</span></span></code></pre></div><p>上述写法均会将 <code>final report</code> 视为一个包含空格的完整词，而不是拆分为两个独立的 AND 关键词。</p><h3 id="粘贴多行文本自动折叠为-or" tabindex="-1">粘贴多行文本自动折叠为 OR <a class="header-anchor" href="#粘贴多行文本自动折叠为-or" aria-label="Permalink to &quot;粘贴多行文本自动折叠为 OR&quot;">​</a></h3><p>当从电子表格、文本文件或日志中复制多行文本（一行一个文件名）并直接粘贴到搜索框中时，Lertaro 会自动将各行用 <code>|</code> 拼接折叠为一条 OR 查询（自动过滤空白行）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>\n<span class="line"><span>456</span></span>\n<span class="line"><span>678</span></span></code></pre></div><p>粘贴后将自动转换为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123 | 456 | 678</span></span></code></pre></div><h2 id="_3-操作符修饰符大全" tabindex="-1">3. 操作符修饰符大全 <a class="header-anchor" href="#_3-操作符修饰符大全" aria-label="Permalink to &quot;3. 操作符修饰符大全&quot;">​</a></h2><h3 id="操作符速查表" tabindex="-1">操作符速查表 <a class="header-anchor" href="#操作符速查表" aria-label="Permalink to &quot;操作符速查表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">操作符 / 语法</th><th style="text-align:left;">类型</th><th style="text-align:left;">效果说明</th><th style="text-align:left;">输入示例</th><th style="text-align:left;">匹配结果示例</th></tr></thead><tbody><tr><td style="text-align:left;"><em>(无)</em></td><td style="text-align:left;">默认模糊</td><td style="text-align:left;">字符按顺序出现在名称任意位置（开启模糊时）</td><td style="text-align:left;"><code>report</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td></tr><tr><td style="text-align:left;"><code>!</code></td><td style="text-align:left;">排除</td><td style="text-align:left;">排除名称中包含该精确子串的所有结果</td><td style="text-align:left;"><code>!temp</code></td><td style="text-align:left;">过滤掉含有 <code>temp</code> 的文件</td></tr><tr><td style="text-align:left;"><code>&#39;</code></td><td style="text-align:left;">翻转精确性</td><td style="text-align:left;">模糊开启时转精确子串；模糊关闭时转模糊匹配</td><td style="text-align:left;"><code>&#39;report</code></td><td style="text-align:left;">必须包含连续的 <code>report</code> 子串</td></tr><tr><td style="text-align:left;"><code>&#39;...&#39;</code></td><td style="text-align:left;">词边界匹配</td><td style="text-align:left;">精确子串匹配，且要求位于单词边界（非单词内部）</td><td style="text-align:left;"><code>&#39;app&#39;</code></td><td style="text-align:left;">匹配 <code>app.exe</code>、<code>my-app.log</code>，不匹配 <code>whatsapp.exe</code></td></tr><tr><td style="text-align:left;"><code>^</code></td><td style="text-align:left;">前缀匹配</td><td style="text-align:left;">文件/文件夹名称必须以该内容开头</td><td style="text-align:left;"><code>^IMG</code></td><td style="text-align:left;"><code>IMG_20240101.jpg</code>（不匹配 <code>MY_IMG.jpg</code>）</td></tr><tr><td style="text-align:left;"><code>$</code></td><td style="text-align:left;">后缀匹配</td><td style="text-align:left;">文件/文件夹名称必须以该内容结尾</td><td style="text-align:left;"><code>.pdf$</code></td><td style="text-align:left;"><code>document.pdf</code>（不匹配 <code>document.pdf.bak</code>）</td></tr><tr><td style="text-align:left;"><code>^...$</code></td><td style="text-align:left;">完全匹配</td><td style="text-align:left;">文件/文件夹名称必须与该内容完全相等</td><td style="text-align:left;"><code>^readme.md$</code></td><td style="text-align:left;">仅精确匹配 <code>readme.md</code></td></tr><tr><td style="text-align:left;"><code>|</code></td><td style="text-align:left;">或逻辑</td><td style="text-align:left;">匹配管道符任意一侧的条件</td><td style="text-align:left;"><code>doc | pdf</code></td><td style="text-align:left;">匹配名称包含 <code>doc</code> 或 <code>pdf</code> 的项</td></tr></tbody></table><h3 id="操作符进阶说明与实战组合" tabindex="-1">操作符进阶说明与实战组合 <a class="header-anchor" href="#操作符进阶说明与实战组合" aria-label="Permalink to &quot;操作符进阶说明与实战组合&quot;">​</a></h3><ol><li><strong>排除修饰符 <code>!</code></strong>：<code>!term</code> 会将包含 <code>term</code> 精确子串的结果直接剔除。排除项不会进行拼音扩展，以避免误排除无辜文件。</li><li><strong>精确性翻转 <code>&#39;</code></strong>：在全局模糊匹配开启的状态下，前缀 <code>&#39;</code> 可使特定关键词临时走精确子串匹配。 <ul><li>例如 <code>lertaro &#39;v1.2</code> 表示 <code>lertaro</code> 走模糊搜索，而 <code>v1.2</code> 必须作为连续字符精准出现。</li><li>即便开启了精确搜索，程序仍将匹配存在拼音别名的文件名，如 <code>&#39;exe$</code> 可搜索到 <code>古恩希尔</code>（拼音映射为 <code>gexe</code>）。</li></ul></li><li><strong>词边界精确匹配 <code>&#39;...&#39;</code></strong>：用单引号包裹单个词（如 <code>&#39;app&#39;</code>）时，匹配引擎会检查前后边界（空白字符、标点符号、减号、下划线或字符串首尾），避免在长单词中间发生误命中。</li><li><strong>完全匹配 <code>^...$</code></strong>：仅当 <code>^</code> 和 <code>$</code> 作用于<strong>同一个词</strong>时生效。如果分别写在不同词上（如 <code>^src md$</code>），则仍分别作为前缀和后缀条件。</li></ol><p><strong>多操作符组合实战示例</strong>：</p><ul><li><code>^IMG !.png$ 2024</code>：查找以 <code>IMG</code> 开头、包含 <code>2024</code>、且后缀<strong>不是</strong> <code>.png</code> 的文件。</li><li><code>&#39;data | &#39;backup ^2024 .zip$</code>：查找以 <code>2024</code> 开头、以 <code>.zip</code> 结尾，且名称中精确包含 <code>data</code> 或 <code>backup</code> 的压缩包。</li><li><code>^report &#39;公告 | &#39;gw .pdf$ !draft</code>：名称以 <code>report</code> 开头、以 <code>.pdf</code> 结尾、不包含 <code>draft</code>，且名称中精确包含 <code>公告</code> 或 <code>gw</code> 或 <code>公文</code> 及其他符合 <code>gw</code> 拼音的文字组合（<code>&#39;公告 | &#39;gw</code> 组成一个 OR 组，其余空格条件与它取 AND）。</li></ul><h2 id="_4-路径模式与盘符限定" tabindex="-1">4. 路径模式与盘符限定 <a class="header-anchor" href="#_4-路径模式与盘符限定" aria-label="Permalink to &quot;4. 路径模式与盘符限定&quot;">​</a></h2><h3 id="指定盘符" tabindex="-1">指定盘符 <a class="header-anchor" href="#指定盘符" aria-label="Permalink to &quot;指定盘符&quot;">​</a></h3><p>在搜索框开头输入盘符加冒号，可将搜索范围严格限定在指定驱动器：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>空格可以省略，<code>d:report</code> 与 <code>d: report</code> 等效。</p><h3 id="完整路径模式" tabindex="-1">完整路径模式 <a class="header-anchor" href="#完整路径模式" aria-label="Permalink to &quot;完整路径模式&quot;">​</a></h3><p>当搜索内容包含路径分隔符（<code>\\</code> 或 <code>/</code>）时，Lertaro 会自动切换为全路径匹配模式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>若以路径分隔符结尾（如 <code>D:\\Projects\\</code>），则会直接检索该文件夹<strong>内部</strong>的所有子项。</p><h3 id="智能上级文件夹回退匹配-folder-matching" tabindex="-1">智能上级文件夹回退匹配（Folder Matching） <a class="header-anchor" href="#智能上级文件夹回退匹配-folder-matching" aria-label="Permalink to &quot;智能上级文件夹回退匹配（Folder Matching）&quot;">​</a></h3><p>当针对文件名的普通搜索未填满结果列表上限时，Lertaro 会自动使用查询词中未命中文件名的部分去匹配上级祖先文件夹名称，无需额外语法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p>即使 <code>dcj</code> 没有出现在文件本身的名字中，也能找到位于名为（或拼音别名为）<code>dcj</code> 的文件夹下的 <code>d01j.txt</code> 文件。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>该特性要求至少有一个词命中文件名本身，且仅在文件名直接匹配未填满结果时触发。回退补全的结果始终排列在常规结果之后，绝不会顶替或打乱文件名直接匹配的结果。</p></div><h2 id="_5-查询标记与二次过滤-query-tokens" tabindex="-1">5. 查询标记与二次过滤（Query Tokens） <a class="header-anchor" href="#_5-查询标记与二次过滤-query-tokens" aria-label="Permalink to &quot;5. 查询标记与二次过滤（Query Tokens）&quot;">​</a></h2><p>Lertaro 支持在主搜索词后追加以冒号 <code>:</code>（可在<strong>设置 → 通用 → 系统 → 查询标记总前导字符</strong>中自定义）引导的<strong>查询标记（Query Tokens）</strong>，对初筛结果进行链式二次过滤与排序。</p><p>支持在单个 <code>:</code> 后使用逗号 <code>,</code> 组合多个标记，例如 <code>report :@doc,M-,:-F</code>。</p><h3 id="文件分类过滤-分类名" tabindex="-1">文件分类过滤（<code>:@&lt;分类名&gt;</code>） <a class="header-anchor" href="#文件分类过滤-分类名" aria-label="Permalink to &quot;文件分类过滤（`:@&lt;分类名&gt;`）&quot;">​</a></h3><p>快速套用预设的扩展名分类规则，支持使用 <code>|</code> 组合多个分类：</p><ul><li><code>:@doc</code>：文档类（<code>*.doc; *.docx; *.pdf; *.txt; *.ppt; *.pptx; *.xls; *.xlsx; *.csv; *.rtf; *.md; *.wps</code>）</li><li><code>:@img</code>：图片类（<code>*.jpg; *.jpeg; *.png; *.gif; *.bmp; *.webp; *.ico; *.svg; *.tif; *.tiff; *.psd; *.ai</code>）</li><li><code>:@video</code>：视频类（<code>*.mp4; *.mkv; *.avi; *.mov; *.wmv; *.flv; *.m4v; *.webm; *.3gp; *.rmvb; *.ts</code>）</li><li><code>:@audio</code>：音频类（<code>*.mp3; *.wav; *.flac; *.aac; *.ogg; *.m4a; *.wma; *.ape</code>）</li><li><code>:@zip</code>：压缩包类（<code>*.zip; *.rar; *.7z; *.tar; *.gz; *.bz2; *.xz; *.iso</code>）</li></ul><p><strong>示例</strong>：</p><ul><li><code>财务 :@doc</code>：在文档中搜索“财务”。</li><li><code>壁纸 :@img</code>：在图片中搜索“壁纸”。</li><li><code>clip :@video|audio</code>：在视频或音频文件中搜索“clip”。</li></ul><p>你可以在<strong>设置 → 插件 → CoreExtensions</strong>中自由修改分类规则或新增自定义分类。</p><h3 id="扩展名精准过滤-ext-或-ext1-ext2" tabindex="-1">扩展名精准过滤（<code>:.ext</code> 或 <code>:.ext1.ext2</code>） <a class="header-anchor" href="#扩展名精准过滤-ext-或-ext1-ext2" aria-label="Permalink to &quot;扩展名精准过滤（`:.ext` 或 `:.ext1.ext2`）&quot;">​</a></h3><p>使用点号直接指定一个或多个文件扩展名（会自动排除文件夹）：</p><ul><li><code>report :.pdf</code>：只保留 <code>.pdf</code> 文件。</li><li><code>data :.csv.xlsx</code>：只保留 <code>.csv</code> 或 <code>.xlsx</code> 表格文件。</li></ul><h3 id="结果排序与文件-目录筛选-scmaf" tabindex="-1">结果排序与文件/目录筛选（<code>:[SCMAF]</code>） <a class="header-anchor" href="#结果排序与文件-目录筛选-scmaf" aria-label="Permalink to &quot;结果排序与文件/目录筛选（`:[SCMAF]`）&quot;">​</a></h3><p>使用单个字母指定排序属性：<code>S</code>（文件大小）、<code>C</code>（创建时间）、<code>M</code>（修改时间）、<code>A</code>（访问时间）、<code>F</code>（文件夹/文件过滤）。</p><p>默认字母代表<strong>升序</strong>（从小到大 / 从旧到新）；添加减号 <code>-</code>（前缀或后缀均可，如 <code>M-</code> 或 <code>:-M</code>）代表<strong>降序</strong>（从大到小 / 从新到旧）或反向过滤：</p><table tabindex="0"><thead><tr><th style="text-align:left;">标记语法</th><th style="text-align:left;">效果说明</th><th style="text-align:left;">典型应用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:S</code></td><td style="text-align:left;">按文件大小升序排列（最小在前）</td><td style="text-align:left;">查找空文件或极小文件</td></tr><tr><td style="text-align:left;"><code>:S-</code> 或 <code>:-S</code></td><td style="text-align:left;">按文件大小降序排列（最大在前）</td><td style="text-align:left;"><code>log :S-</code>（排查体积最大的日志文件）</td></tr><tr><td style="text-align:left;"><code>:M</code></td><td style="text-align:left;">按修改时间升序排列（最早修改在前）</td><td style="text-align:left;">查找长期未更新的历史文件</td></tr><tr><td style="text-align:left;"><code>:M-</code> 或 <code>:-M</code></td><td style="text-align:left;">按修改时间降序排列（最新修改在前）</td><td style="text-align:left;"><code>report :M-</code>（快速查找最近修改过的文档）</td></tr><tr><td style="text-align:left;"><code>:C</code> / <code>:C-</code></td><td style="text-align:left;">按创建时间升序 / 降序排列</td><td style="text-align:left;"><code>build :C-</code>（查找最新生成的构建产物）</td></tr><tr><td style="text-align:left;"><code>:A</code> / <code>:A-</code></td><td style="text-align:left;">按访问时间升序 / 降序排列</td><td style="text-align:left;"><code>project :A-</code>（查找最近打开过的工程）</td></tr><tr><td style="text-align:left;"><code>:F</code></td><td style="text-align:left;"><strong>仅保留文件夹</strong>（过滤掉所有普通文件）</td><td style="text-align:left;"><code>config :F</code>（仅查找名为 config 的目录）</td></tr><tr><td style="text-align:left;"><code>:-F</code> 或 <code>:F-</code></td><td style="text-align:left;"><strong>仅保留文件</strong>（过滤掉所有文件夹目录）</td><td style="text-align:left;"><code>config :-F</code>（仅查找名为 config 的文件）</td></tr></tbody></table><h3 id="通配符二次过滤-表达式-或-表达式" tabindex="-1">通配符二次过滤（<code>:?&lt;表达式&gt;</code> 或 <code>?&lt;表达式&gt;</code>） <a class="header-anchor" href="#通配符二次过滤-表达式-或-表达式" aria-label="Permalink to &quot;通配符二次过滤（`:?&lt;表达式&gt;` 或 `?&lt;表达式&gt;`）&quot;">​</a></h3><p>使用标准 Windows 通配符（<code>?</code> 匹配单个字符，<code>*</code> 匹配任意字符序列）对结果进行精确匹配，支持用 <code>|</code> 或 <code>;</code> 分隔多个 OR 条件：</p><ul><li><code>mp4 :?(2026???????????)</code>：匹配包含 <code>2026</code> 且后跟 11 位时间戳的视频文件。</li><li><code>photo :?IMG_????.jpg|DSC_????.jpg</code>：同时匹配两种相机格式的特定照片编号。</li></ul><h3 id="路径模糊二次匹配-路径表达式" tabindex="-1">路径模糊二次匹配（<code>::&lt;路径表达式&gt;</code>） <a class="header-anchor" href="#路径模糊二次匹配-路径表达式" aria-label="Permalink to &quot;路径模糊二次匹配（`::&lt;路径表达式&gt;`）&quot;">​</a></h3><p>要求结果的任意一级上级目录名或文件名本身匹配指定的模糊关键词：</p><ul><li><code>report ::2024</code>：要求文件所在路径的各级目录中必须包含 <code>2024</code>。</li><li><code>main ::&quot;src\\core&quot;</code>：要求文件位于 <code>src\\core</code> 及其子目录下。</li></ul><h3 id="链式组合实战示例" tabindex="-1">链式组合实战示例 <a class="header-anchor" href="#链式组合实战示例" aria-label="Permalink to &quot;链式组合实战示例&quot;">​</a></h3><p>各个标记可以组合在同一个 <code>:</code> 后使用：</p><ul><li><code>财务报表 :@doc,M-</code>：搜索“财务报表”，限定文档类型，按修改时间倒序排列（最新修改在前）。</li><li><code>backup :.zip,S-,:-F</code>：搜索“backup”，限定 <code>.zip</code> 格式，按体积从大到小排列，且仅显示文件。</li><li><code>icon ::assets,?*128*</code>：搜索“icon”，限定路径包含 <code>assets</code>，且文件名中包含 <code>128</code> 尺寸标识。</li></ul><h2 id="_6-特殊搜索技巧" tabindex="-1">6. 特殊搜索技巧 <a class="header-anchor" href="#_6-特殊搜索技巧" aria-label="Permalink to &quot;6. 特殊搜索技巧&quot;">​</a></h2><h3 id="单次搜索临时绕过排除规则" tabindex="-1">单次搜索临时绕过排除规则 <a class="header-anchor" href="#单次搜索临时绕过排除规则" aria-label="Permalink to &quot;单次搜索临时绕过排除规则&quot;">​</a></h3><p>在查询最开头输入 <code>*</code>，可让本次搜索临时忽略在<a href="./settings/index-drives.html#排除规则"><strong>排除规则</strong></a>中配置的路径排除、Glob 和正则表达式，无需修改设置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p><code>*</code> 本身会在搜索前自动剥离，不会参与文本匹配。该功能仅能召回已索引的内容（网络盘或 WSL 中未被索引的排除项不会出现）；系统隐藏文件等基础过滤依然保持生效。</p><h3 id="结果类型触发符" tabindex="-1">结果类型触发符 <a class="header-anchor" href="#结果类型触发符" aria-label="Permalink to &quot;结果类型触发符&quot;">​</a></h3><p>在<strong>设置 → 通用 → 快速搜索窗口 → 结果类型优先级</strong>中，可以为特定结果类型（应用程序、系统设置、文件分类、插件条目、普通文件等）配置单字符<strong>触发符</strong>。</p><p>在快速搜索栏最前面输入该触发符，将只显示该类型的结果，其他类型全部隐藏：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>若 <code>;</code> 被配置为“应用程序”类型的触发符，上述输入将只在应用程序中检索 Visual Studio。在快速搜索与内嵌窗口中，历史记录与收藏夹不受触发符影响，始终置顶展示。</p><h2 id="_7-多语言智能别名" tabindex="-1">7. 多语言智能别名 <a class="header-anchor" href="#_7-多语言智能别名" aria-label="Permalink to &quot;7. 多语言智能别名&quot;">​</a></h2><h3 id="中文文件名-拼音别名" tabindex="-1">中文文件名：拼音别名 <a class="header-anchor" href="#中文文件名-拼音别名" aria-label="Permalink to &quot;中文文件名：拼音别名&quot;">​</a></h3><p>内置拼音别名插件（<code>PinyinAlias</code>），无需配置即可直接使用拼音检索中文文件名：</p><ul><li><strong>全拼检索</strong>：输入 <code>chongqing</code> 即可精准命中名为 <code>重庆.docx</code> 的文件。</li><li><strong>简拼 / 首字母</strong>：输入 <code>cq</code> 同样可匹配 <code>重庆.docx</code>；输入 <code>wzry</code> 可匹配 <code>王者荣耀.exe</code>。</li><li><strong>多音字支持</strong>：系统会为汉字的常见读音同时建立别名索引（如“重庆”可同时匹配 <code>chongqing</code> 与 <code>zhongqing</code>，“银行”可匹配 <code>yinhang</code> 与 <code>yinxing</code>）。</li></ul><p>可在<strong>设置 → 插件</strong>中确认 <code>PinyinAlias</code> 插件是否处于启用状态。</p><h3 id="西班牙语文件名-重音别名" tabindex="-1">西班牙语文件名：重音别名 <a class="header-anchor" href="#西班牙语文件名-重音别名" aria-label="Permalink to &quot;西班牙语文件名：重音别名&quot;">​</a></h3><p>内置 <code>SpanishAlias</code> 插件，支持使用标准无重音 ASCII 字母检索包含西班牙语重音字符（<code>á</code>、<code>é</code>、<code>í</code>、<code>ó</code>、<code>ú</code>、<code>ü</code>、<code>ñ</code>）的文件名：</p><ul><li>输入 <code>cancion</code> 匹配 <code>Canción.mp3</code>。</li><li>输入 <code>nino</code> 匹配 <code>Niño.txt</code>。</li><li>输入 <code>ciguena</code> 匹配 <code>Cigüeña.png</code>。</li></ul><p>命中的字符（包含原文件名中的重音字符）将保持精准高亮。可在<strong>设置 → 插件</strong>中管理 <code>SpanishAlias</code> 插件。</p><h2 id="_8-常见疑问与收藏夹" tabindex="-1">8. 常见疑问与收藏夹 <a class="header-anchor" href="#_8-常见疑问与收藏夹" aria-label="Permalink to &quot;8. 常见疑问与收藏夹&quot;">​</a></h2><h3 id="收藏夹-而非自定义别名" tabindex="-1">收藏夹，而非自定义别名 <a class="header-anchor" href="#收藏夹-而非自定义别名" aria-label="Permalink to &quot;收藏夹，而非自定义别名&quot;">​</a></h3><p>Lertaro 并未设计通用的“自定义搜索别名/宏”机制。最接近的替代方案是<a href="./settings/favorites.html"><strong>收藏夹</strong></a>：将任意文件、文件夹或网址收藏为自定义显示名称后，即可通过该名称直接搜到它（结果中带有 ★ 标记）。</p><p>如果你需要通过自定义关键词快速启动外部程序或执行脚本，请参阅<a href="./instant-answers.html#自定义命令"><strong>自定义命令</strong></a>。</p>',103)])])}const x=t(c,[["render",l]]);export{g as __pageData,x as default};
